/**
 * SpaceRegistry — EAOIN 1.0 space expansion.
 *
 * Stars, planets, galaxies, anomalies, civilizations, etc.
 * Millions of procedural planets are generated by seed; we list a curated
 * sample here plus the catalog of star/galaxy types.
 */

export type StarClass = 'O' | 'B' | 'A' | 'F' | 'G' | 'K' | 'M' | 'Brown Dwarf' | 'White Dwarf' | 'Neutron Star' | 'Pulsar' | 'Black Hole' | 'Quasar' | 'Binary' | 'Variable' | 'Protostar';

export interface StarSystemDef {
  id: string;
  name: string;
  starClass: StarClass;
  planetCount: number;
  galaxy: string;
  distance: number; // light years
  discovered: boolean;
  colonized: boolean;
  hazards: string[];
  specialFeatures: string[];
}

export interface PlanetDef {
  id: string;
  name: string;
  system: string;
  type: 'terrestrial' | 'gas_giant' | 'ice' | 'lava' | 'ocean' | 'desert' | 'forest' | 'barren' | 'moon' | 'ringed' | 'dark' | 'crystal' | 'alien';
  size: number; // earth radii
  gravity: number; // G
  atmosphere: 'none' | 'thin' | 'normal' | 'thick' | 'toxic' | 'corrosive';
  temperature: number; // K
  habitability: number; // 0-1
  resources: string[];
  life: string[];
  anomalies: string[];
  procedurallyGenerated: boolean;
}

