export const ALL_STAR_SYSTEMS: StarSystemDef[] = STAR_SYSTEMS;
export const ALL_PLANETS: PlanetDef[] = PLANETS;

export function getStarSystem(id: string): StarSystemDef | undefined {
  return ALL_STAR_SYSTEMS.find((s) => s.id === id);
}

export function getPlanet(id: string): PlanetDef | undefined {
  return ALL_PLANETS.find((p) => p.id === id);
}

export function getPlanetsBySystem(systemId: string): PlanetDef[] {
  return ALL_PLANETS.filter((p) => p.system === systemId);
}

export interface StarDef {
  id: string;
  name: string;
  type: StarClass;
  mass: number;
  temperature: number;
  planets: string[];
}

